package dev.veltraph.client.inventory;
import org.junit.jupiter.api.Test;
import net.minecraft.nbt.*;
import static org.junit.jupiter.api.Assertions.*;
class NativeStackCanonicalIdentityTest {
    private static CompoundTag data(boolean reverse){var tag=new CompoundTag();var nested=new CompoundTag();if(reverse){nested.putString("z","last");nested.putInt("a",1);tag.put("components",nested);tag.putString("item","minecraft:diamond_sword");tag.putInt("count",1);}else{nested.putInt("a",1);nested.putString("z","last");tag.putInt("count",1);tag.putString("item","minecraft:diamond_sword");tag.put("components",nested);}return tag;}
    @Test void insertionOrderAndSerializationCopyPreserveStructuralEncoding(){var a=data(false);var b=data(true);assertEquals(a,b);assertEquals(NativeStackIdentity.canonicalPersistentEncoding(a,new CompoundTag()),NativeStackIdentity.canonicalPersistentEncoding(b,new CompoundTag()));assertEquals(NativeStackIdentity.canonicalPersistentEncoding(a,new CompoundTag()),NativeStackIdentity.canonicalPersistentEncoding(a.copy(),new CompoundTag()));}
    @Test void numericTypesArraysAndComponentValuesRemainDistinct(){var base=data(false);var typed=base.copy();typed.putByte("count",(byte)1);assertNotEquals(NativeStackIdentity.canonicalPersistentEncoding(base,new CompoundTag()),NativeStackIdentity.canonicalPersistentEncoding(typed,new CompoundTag()));for(String key:new String[]{"damage","lore","enchantment","trim"}){var c=new CompoundTag();c.putString(key,"changed");assertNotEquals(NativeStackIdentity.canonicalPersistentEncoding(base,new CompoundTag()),NativeStackIdentity.canonicalPersistentEncoding(base,c));}var a=new CompoundTag();a.putByteArray("array",new byte[]{1,2});var b=new CompoundTag();b.putIntArray("array",new int[]{1,2});assertNotEquals(NativeStackIdentity.canonicalPersistentEncoding(base,a),NativeStackIdentity.canonicalPersistentEncoding(base,b));}
    @Test void listOrderIsSignificantAndNestedCompoundsSort(){var a=new ListTag();a.add(data(false));a.add(StringTag.valueOf("second"));var b=new ListTag();b.add(data(true));b.add(StringTag.valueOf("second"));assertEquals(NativeStackIdentity.canonicalPersistentEncoding(a,new CompoundTag()),NativeStackIdentity.canonicalPersistentEncoding(b,new CompoundTag()));var reversed=new ListTag();reversed.add(StringTag.valueOf("second"));reversed.add(data(true));assertNotEquals(NativeStackIdentity.canonicalPersistentEncoding(a,new CompoundTag()),NativeStackIdentity.canonicalPersistentEncoding(reversed,new CompoundTag()));}
}
